mapper.select:
select membership_id, issuer, subject, user_id, tenant_id, program_id, data_scope_id, status,
       valid_from, valid_until, metadata_snapshot_id, locale, timezone, reporting_currency,
       as_of, data_watermark
  from campaign_membership
 where issuer = #{issuer}
   and subject = #{subject}
   and selection_key is not distinct from #{selectionKey, jdbcType=VARCHAR}
   and status = 'ACTIVE'
 order by membership_id
